var SEQ=1;
function add(list, text, color){ if(!text||!text.trim()) return list; return list.concat([{id:SEQ++, text:text.trim(), color:color||'#fff7a8'}]); }
function update(list, id, text){ return list.map(function(x){ return x.id===id? Object.assign({},x,{text:text}) : x; }); }
function remove(list, id){ return list.filter(function(x){ return x.id!==id; }); }
var EXPORTS={add:add,update:update,remove:remove};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.StickyNoteForgePure = EXPORTS; }
